def max_xor(root, num, B=31):
    node = root
    best = 0
    for b in range(B, -1, -1):
        bit = (num >> b) & 1
        want = 1 - bit
        if want in node.children:
            best |= 1 << b
            node = node.children[want]
        else:
            node = node.children[bit]
    return best

